// Package contract mirrors packages/usage-core: the UsageSnapshot shape, its
// fail-closed validation, and the exact serialization the server's dedup hash
// is computed over. Byte-level drift here breaks ingest dedup and burns D1
// quota, so the goldens in goldens/ are produced by the TypeScript
// implementation and must never be regenerated by hand.
package contract

import (
	_ "embed"
	"encoding/json"
	"strings"
	"testing"
	"time"
)

//go:embed goldens/snapshot-hash.json
var snapshotHashGoldens []byte

// goldenCase is one entry of goldens/snapshot-hash.json, produced by
// packages/usage-core's snapshotHashPayload for the same logical snapshot.
type goldenCase struct {
	Name        string `json:"name"`
	Key         string `json:"key"`
	HashPayload string `json:"hashPayload"`
}

func loadGoldenCases(t *testing.T) []goldenCase {
	t.Helper()
	var cases []goldenCase
	if err := json.Unmarshal(snapshotHashGoldens, &cases); err != nil {
		t.Fatalf("parse goldens: %v", err)
	}
	if len(cases) == 0 {
		t.Fatal("no golden cases")
	}
	return cases
}

// goldenSnapshotByName rebuilds the snapshot each golden was generated from.
// Keep this in lockstep with scripts that regenerate the goldens (see
// goldens/README.md).
func goldenSnapshotByName(t *testing.T, name string) Snapshot {
	t.Helper()
	base := Snapshot{
		Source:       SourceCodex,
		UsageDate:    "2026-05-09",
		Timezone:     "Asia/Shanghai",
		Model:        "gpt-5",
		InputTokens:  10,
		OutputTokens: 2,
		TotalTokens:  17,
		CacheRead:    5,
		CostUSD:      0.01,
		SessionCount: 1,
		CollectedAt:  "2026-05-09T10:00:00.000Z",
	}
	switch name {
	case "base":
		return base
	case "with-correction":
		base.Correction = CorrectionCodexContextPricing
		return base
	case "cost-unavailable-grok":
		base.Source = SourceGrokBuild
		base.CostUSD = 0
		return base
	case "all-zero":
		base.InputTokens, base.OutputTokens, base.CacheCreation = 0, 0, 0
		base.CacheRead, base.TotalTokens = 0, 0
		base.CostUSD, base.SessionCount = 0, 0
		return base
	case "unicode-model":
		base.Model = "módel/中文-模型"
		return base
	case "extreme-tokens":
		base.InputTokens, base.TotalTokens = MaxSnapshotTokens, MaxSnapshotTokens
		return base
	case "fractional-cost":
		// Runtime arithmetic: Go's constant folder would round 0.1+0.2
		// exactly once (giving exactly 0.3's double), while TS computes it
		// at runtime and lands one ulp higher. The golden bytes come from
		// the runtime result, so this must be runtime arithmetic too.
		a, b := 0.1, 0.2
		base.CostUSD = a + b
		return base
	case "timezone-etc-gmt":
		base.Timezone = "Etc/GMT+5"
		return base
	default:
		t.Fatalf("unknown golden case %q", name)
		return Snapshot{}
	}
}

func TestSnapshotHashPayloadMatchesTypeScriptGoldens(t *testing.T) {
	for _, golden := range loadGoldenCases(t) {
		t.Run(golden.Name, func(t *testing.T) {
			snapshot := goldenSnapshotByName(t, golden.Name)
			if got := snapshot.HashPayload(); got != golden.HashPayload {
				t.Errorf("hash payload drift\ngot:  %s\nwant: %s", got, golden.HashPayload)
			}
			if got := SnapshotKey(snapshot.Source, snapshot.UsageDate, snapshot.Model); got != golden.Key {
				t.Errorf("key drift: got %q want %q", got, golden.Key)
			}
		})
	}
}

// The payload must be byte-identical to TS JSON.stringify for the float cases
// too: encoding/json is not trusted for this (map key order, float formatting
// differs across Go versions), which is why HashPayload assembles by hand.
func TestHashPayloadDoesNotDependOnEncodingJSONFloats(t *testing.T) {
	snapshot := goldenSnapshotByName(t, "fractional-cost")
	// 0.1+0.2 in IEEE double is 0.30000000000000004; TS JSON.stringify emits
	// the shortest round-trip form, which Go's strconv.FormatFloat(-1) matches.
	if !strings.Contains(snapshot.HashPayload(), `"costUsd":0.30000000000000004`) {
		t.Errorf("unexpected float form: %s", snapshot.HashPayload())
	}
}

func TestSnapshotKeyUsesNULSeparator(t *testing.T) {
	if got := SnapshotKey(SourceCodex, "2026-05-09", "gpt-5"); got != "codex\x002026-05-09\x00gpt-5" {
		t.Errorf("key: got %q", got)
	}
}

// Validation must reject what the Zod superRefine rejects, with the same
// shape of rule: cross-field and cost-unavailability, not just field shapes.
func TestValidateFailClosedCases(t *testing.T) {
	cases := []struct {
		name    string
		mutate  func(*Snapshot)
		wantErr string
	}{
		{
			name:    "cacheRead exceeds total",
			mutate:  func(s *Snapshot) { s.CacheRead = 100; s.TotalTokens = 17 },
			wantErr: "cacheReadTokens must not exceed totalTokens",
		},
		{
			name:    "grok cost must be zero",
			mutate:  func(s *Snapshot) { s.Source = SourceGrokBuild; s.CostUSD = 0.5 },
			wantErr: "Grok Build source costs are unavailable; costUsd must be 0",
		},
		{
			name:    "dsh cost must be zero",
			mutate:  func(s *Snapshot) { s.Source = SourceDeepSeekHarness; s.CostUSD = 0.5 },
			wantErr: "DeepSeek Harness source costs are unavailable; costUsd must be 0",
		},
		{
			name:    "antigravity cost must be zero",
			mutate:  func(s *Snapshot) { s.Source = SourceAntigravity; s.CostUSD = 0.5 },
			wantErr: "Antigravity source costs are unavailable; costUsd must be 0",
		},
		{
			name:    "negative tokens",
			mutate:  func(s *Snapshot) { s.InputTokens = -1 },
			wantErr: "inputTokens",
		},
		{
			name:    "token ceiling",
			mutate:  func(s *Snapshot) { s.InputTokens = MaxSnapshotTokens + 1 },
			wantErr: "inputTokens",
		},
		{
			name:    "cost ceiling",
			mutate:  func(s *Snapshot) { s.CostUSD = MaxSnapshotCostUSD + 1 },
			wantErr: "costUsd",
		},
		{
			name:    "empty model",
			mutate:  func(s *Snapshot) { s.Model = "" },
			wantErr: "model",
		},
		{
			name:    "unknown source",
			mutate:  func(s *Snapshot) { s.Source = Source("kimi") },
			wantErr: "source",
		},
		{
			name:    "bad iso date",
			mutate:  func(s *Snapshot) { s.UsageDate = "2026-02-30" },
			wantErr: "usageDate",
		},
		{
			name:    "non-canonical date",
			mutate:  func(s *Snapshot) { s.UsageDate = "2026-5-9" },
			wantErr: "usageDate",
		},
		{
			name:    "empty timezone",
			mutate:  func(s *Snapshot) { s.Timezone = "  " },
			wantErr: "timezone",
		},
		{
			name:    "timezone with surrounding whitespace",
			mutate:  func(s *Snapshot) { s.Timezone = " Asia/Shanghai" },
			wantErr: "timezone",
		},
		{
			name:    "unknown timezone",
			mutate:  func(s *Snapshot) { s.Timezone = "Mars/Olympus" },
			wantErr: "timezone",
		},
		{
			name:    "unknown correction literal",
			mutate:  func(s *Snapshot) { s.Correction = "codex-other" },
			wantErr: "correction",
		},
		{
			name:    "collectedAt not RFC3339",
			mutate:  func(s *Snapshot) { s.CollectedAt = "2026-05-09 10:00:00" },
			wantErr: "collectedAt",
		},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			snapshot := goldenSnapshotByName(t, "base")
			tc.mutate(&snapshot)
			err := snapshot.Validate()
			if err == nil {
				t.Fatalf("expected error %q, got nil", tc.wantErr)
			}
			if !strings.Contains(err.Error(), tc.wantErr) {
				t.Errorf("error %q does not mention %q", err, tc.wantErr)
			}
		})
	}
}

func TestValidateAcceptsGoldenBase(t *testing.T) {
	if err := goldenSnapshotByName(t, "base").Validate(); err != nil {
		t.Fatalf("base snapshot must validate: %v", err)
	}
	if err := goldenSnapshotByName(t, "extreme-tokens").Validate(); err != nil {
		t.Fatalf("max tokens must validate: %v", err)
	}
}

// Mirrors usage-core isValidIsoDate: canonical YYYY-MM-DD and a real calendar
// date (2026-02-30 is rejected even though the shape matches).
func TestIsValidIsoDate(t *testing.T) {
	valid := []string{"2023-01-01", "2026-12-31", "2024-02-29"}
	invalid := []string{"2026-02-30", "2026-5-9", "26-05-09", "2026-13-01", "2026-05-09T00:00:00Z", ""}
	for _, value := range valid {
		if !IsValidIsoDate(value) {
			t.Errorf("%q should be valid", value)
		}
	}
	for _, value := range invalid {
		if IsValidIsoDate(value) {
			t.Errorf("%q should be invalid", value)
		}
	}
}

func TestIsValidTimezone(t *testing.T) {
	valid := []string{"Asia/Shanghai", "UTC", "Etc/GMT+5", "America/New_York"}
	invalid := []string{"Mars/Olympus", " Asia/Shanghai", "", "Asia/Shanghai "}
	for _, value := range valid {
		if !IsValidTimezone(value) {
			t.Errorf("%q should be valid", value)
		}
	}
	for _, value := range invalid {
		if IsValidTimezone(value) {
			t.Errorf("%q should be invalid", value)
		}
	}
}

// tzdata must be embedded: Windows and slim containers have no system zone
// database, and the collector validates arbitrary user timezones.
func TestTzdataEmbedded(t *testing.T) {
	if _, err := time.LoadLocation("America/New_York"); err != nil {
		t.Fatalf("embedded tzdata missing: %v", err)
	}
}
